const text = $input.first().json.body.candidates[0].content.parts[0].text;
const parsedArray = JSON.parse(text);
const output = [];
const docName = $('Get pdf info').first().json.originalFilename || "";

// Get the document ID from Supabase - Create Document
const documentId = $('Supabase - Create Document').first().json.id;

// Fields we want to guarantee in every role block
const guaranteedFields = ["contacto_mail", "tipo_camion", "vehiculo"];

parsedArray.forEach((cmr) => {
  const roles = ["expedidor", "destinatario", "transportista"];

  // Get the overall confidence score for the document
  const Confidence_Score = cmr.confidence_score || 0;

  roles.forEach(role => {
    const data = cmr[role] || {};

    // Fill in missing guaranteed fields with empty string
    guaranteedFields.forEach(field => {
      if (!(field in data)) {
        data[field] = "";
      }
    });

    output.push({
      json: {
        documento: docName,
        document_id: documentId,  // Add the document UUID here
        role,
        confidence_score: Confidence_Score,  // Document-level confidence
        ...data
      }
    });
  });
});

return output;

return $input.all().map(item => {
  const url = item.json.website;
  if (!url) return null; // Skip if url missing

  let domain = url
    .replace(/^https?:\/\//, "")     // remove http/https
    .replace(/^www\./, "")           // remove www.
    .replace(/\/.*/, "")             // remove everything after first /
    .replace(/\n/, "")               // remove any line break
    .trim();

  // Skip if it's a known social network or invalid
  const blocked = ["facebook.com", "linkedin.com", "instagram.com", "google.com"];
  if (blocked.some(bad => domain.includes(bad))) return null;

  return { json: { domain } };
}).filter(Boolean); // Remove nulls

