};
const local_results = $json.local_results;

// --- Simple normalization helpers ---
function norm(s) { return (s||'').toLowerCase().replace(/[^a-z0-9]/g, ''); }
function normPhone(s) { return (s||'').replace(/\D/g,''); }
function postal(addr) { const m = (addr||'').match(/\b\d{5}\b/); return m ? m[0] : ''; }
function city(addr) { 
  const m = (addr||'').match(/[0-9]{5}\s+([^\d,]+)/i); 
  return m ? m[1].trim().toLowerCase() : ''; 
}

const wantedPostal = postal(input.direccion);
const wantedCity = city(input.direccion);
const wantedName = norm(input.empresa);
const wantedPhone = normPhone(input.contacto_tel);

const mainMatch = norm("Cargo-Service Internationale Spedition GmbH");
const partialMatch = norm("Cargo-Service");

const scored = (local_results || []).map(res => {
  const resPostal = postal(res.address);
  const resCity = city(res.address);
  const resName = norm(res.title);
  const resPhone = normPhone(res.phone);

  let score = 0;
  if (wantedPostal && resPostal && wantedPostal === resPostal) score += 4;
  if (wantedCity && resCity && wantedCity === resCity) score += 3;
  if (wantedPhone && resPhone && wantedPhone.slice(-7) === resPhone.slice(-7)) score += 4;
  if (resName.includes(mainMatch)) score += 5;
  else if (resName.includes(partialMatch)) score += 2;

  return {...res, score, debug: {resPostal, resCity, resName, resPhone}};
});

scored.sort((a,b) => b.score - a.score);

return scored.map(item => ({json: item}));

// Get original data - this should always exist
const originalData = $("Loop Over Roles").first()?.json || {};

// Try to get enrichment data if nodes executed
let selectedData = {};
let hunterData = {};
let firecrawlData = {};
let firecrawlData2 = {};


try {
