// Phone standardization function
function standardizePhone(phone) {
  if (!phone || typeof phone !== 'string') return "";

  let cleaned = phone.replace(/\D/g, '');

  if (phone.trim().startsWith('+')) {
    cleaned = '00' + cleaned;
  }

  if (cleaned.length === 9) {
    if (cleaned.match(/^[679]/)) {
      cleaned = '0034' + cleaned;
    }
  } else if (cleaned.length === 10 && !cleaned.startsWith('00')) {
    cleaned = '0049' + cleaned;
  }

  if (cleaned.match(/^(34|49|44|33|39|351|32|31)\d{8,}/)) {
    cleaned = '00' + cleaned;
  }

  return cleaned;
}

// Determine which enrichment path was taken
// Three possible paths: firecrawl, hunterIO, or none
const enrichmentType = firecrawlData.success === true ? "firecrawl" : 
hunterData.data ? "hunterIO" : 
                    "none";

// Build merged result with data priority
const mergedResult = {
  documento: originalData.documento ?? "",
  role: originalData.role ?? "",
  empresa: originalData.empresa ?? "",
  contacto_tel: standardizePhone(
    firecrawlData2.telefono || 
    selectedData.phone || 
    originalData.contacto_tel || 
    ""
  ),
  direccion: firecrawlData2.direccion || 
    selectedData.address || 
    originalData.direccion || 
    "",
  contacto_fax: standardizePhone(originalData.contacto_fax ?? ""),
  contacto_mail: firecrawlData2.email || 
    (hunterData.data?.emails?.[1]?.value) || 
    originalData.contacto_mail || 
    "",
  tipo_camion: originalData.tipo_camion ?? "",
  vehiculo: originalData.vehiculo ?? "",
  enrichmentType: enrichmentType
};

// Add website if available from any source
if (firecrawlData2.website || selectedData.website) {
  mergedResult.website = firecrawlData2.website || selectedData.website;
}

// Add match score if Firecrawl was used
if (enrichmentType === "firecrawl") {
  mergedResult.matchScore = firecrawlData2.matchScore;
}



// ADD THIS TO THE END OF YOUR EXISTING GATHER & FLATTEN CODE

// Get workflow static data to accumulate across loop runs
const staticData = $getWorkflowStaticData('global');

// Initialize accumulator if this is the first run
if (!staticData.apiAccumulator) {
  staticData.apiAccumulator = {
    documentId: $('Supabase - Create Document').first()?.json?.id || 'unknown',
    documentName: $('Get pdf info').first()?.json?.originalFilename || 'unknown',
    roles: [],
    apiUsage: {
      gemini_ocr: 1,  // Always 1 per document
      serpapi: 0,
      hunter: 0,
      firecrawl: 0
    }
  };
}

// Add current role data to accumulator
staticData.apiAccumulator.roles.push({
  role: mergedResult.role,
  enrichmentType: mergedResult.enrichmentType,
  empresa: mergedResult.empresa
});

// Update API usage based on current enrichment type
switch(mergedResult.enrichmentType) {
  case 'firecrawl':
    staticData.apiAccumulator.apiUsage.serpapi++;
    staticData.apiAccumulator.apiUsage.firecrawl++;
    break;

  case 'hunterIO':
    staticData.apiAccumulator.apiUsage.serpapi++;
    staticData.apiAccumulator.apiUsage.hunter++;
    break;
}

// Check if this is the last role
const isComplete = staticData.apiAccumulator.roles.length === 3;

// Add accumulated data to current output
mergedResult.apiTracking = {
  isComplete: isComplete,
  rolesProcessed: staticData.apiAccumulator.roles.length,
  accumulatedUsage: { ...staticData.apiAccumulator.apiUsage },
  allRoles: [...staticData.apiAccumulator.roles]
};

// If complete, include final data and reset
if (isComplete) {
  mergedResult.apiTracking.finalData = { ...staticData.apiAccumulator };
  staticData.apiAccumulator = null;
}

// Return the enriched data with API tracking
return [{ json: mergedResult }];

