// Simple validation with fuzzy matching
const firecrawlResult = $json;
const targetCompany = $('Loop Over Roles').item.json.empresa.toLowerCase().trim();

// Function to calculate fuzzy match score
function fuzzyMatch(str1, str2) {
  str1 = str1.toLowerCase().trim();
  str2 = str2.toLowerCase().trim();

  // Exact match
  if (str1 === str2) return 1;

  // One contains the other
  if (str1.includes(str2) || str2.includes(str1)) return 0.9;

  // Calculate similarity
  const longer = str1.length > str2.length ? str1 : str2;
  const shorter = str1.length > str2.length ? str2 : str1;

  let matches = 0;
  for (let i = 0; i < shorter.length; i++) {
    if (longer.includes(shorter[i])) matches++;
  }

  return matches / longer.length;
}
// Check if we have results
if (firecrawlResult.success && firecrawlResult.data) {
  const extractedData = firecrawlResult.data[0]?.extract || firecrawlResult.data.extract;

  if (extractedData && extractedData.empresa) {
    const foundCompany = extractedData.empresa || extractedData.companyNameFound || '';
    const matchScore = fuzzyMatch(targetCompany, foundCompany);

    // Accept if match score > 70%
    if (matchScore > 0.75) {
      return [{
        json: {
          empresa: targetCompany,
          direccion: extractedData.direccion || null,
          telefono: extractedData.telefono || null,
          website: extractedData.website || null,
          email: extractedData.email || null,
          matchScore: matchScore,
          foundName: foundCompany,
          validated: true
        }
      }];
    }
  }
}

// No valid match found
return [{
  json: {
    empresa: targetCompany,
    direccion: null,
    telefono: null,
    website: null,
    email: null,
    matchScore: 0,
    validated: false,
    error: "Company name doesn't match"
  }
}];

// ===== API COST TRACKING NODE =====

// Gemini Pricing Configuration (per million tokens)
const GEMINI_PRICING = {
  input_per_million: 1.25,
  output_per_million: 10
};

// Get the last item from Gather & Flatten which should have complete data
const lastGatherData = $('Gather & Flatten data').first()?.json;

// Get Gemini data from both nodes
const geminiUploadNode = $('Gemini-Upload').first();
const geminiAskNode = $('Gemini-Ask question').first();

// Extract usage metadata from the Ask node
const geminiUsageMetadata = geminiAskNode?.json?.body?.usageMetadata;

// Get file info from Upload node if needed
const uploadedFile = geminiUploadNode?.json?.file;

// Check if we have accumulated API tracking data
if (!lastGatherData?.apiTracking?.isComplete) {
  return [{
    json: {
      error: "API tracking incomplete",
      message: "Not all roles have been processed",
      rolesFound: lastGatherData?.apiTracking?.rolesProcessed || 0
    }
  }];
}

// Get the accumulated data
const apiUsage = lastGatherData.apiTracking.finalData.apiUsage;
const enrichmentData = lastGatherData.apiTracking.finalData.roles;
const documentId = lastGatherData.apiTracking.finalData.documentId;
const documentName = lastGatherData.apiTracking.finalData.documentName;

// Calculate Gemini cost if usage metadata is available
let geminiCost = 0;
let geminiTokenDetails = null;

if (geminiUsageMetadata) {
  const inputTokens = geminiUsageMetadata.promptTokenCount || 0;
  const outputTokens = (geminiUsageMetadata.candidatesTokenCount || 0) + (geminiUsageMetadata.thoughtsTokenCount || 0);

  const inputCost = (inputTokens / 1_000_000) * GEMINI_PRICING.input_per_million;
  const outputCost = (outputTokens / 1_000_000) * GEMINI_PRICING.output_per_million;

  geminiCost = inputCost + outputCost;

  geminiTokenDetails = {
    input_tokens: inputTokens,
    output_tokens: outputTokens,
    total_tokens: geminiUsageMetadata.totalTokenCount || (inputTokens + outputTokens),
    input_cost: parseFloat(inputCost.toFixed(6)),
    output_cost: parseFloat(outputCost.toFixed(6)),
    total_cost: parseFloat(geminiCost.toFixed(6)),
    // Include token breakdown by modality
    token_breakdown: geminiUsageMetadata.promptTokensDetails || []
  };
}

// Prepare output record
const costRecord = {
  document_id: documentId,
  document_name: documentName,

  // Gemini cost and details
  gemini_cost: parseFloat(geminiCost.toFixed(6)),
  gemini_tokens: geminiTokenDetails,

  // File info from upload (if needed)
  file_info: uploadedFile ? {
    size_bytes: uploadedFile.sizeBytes,
    mime_type: uploadedFile.mimeType,
    file_name: uploadedFile.name
  } : null,

  // API usage counts only (no costs)
  api_usage: {
    gemini_ocr: apiUsage.gemini_ocr || 0,
    serpapi: apiUsage.serpapi || 0,
    hunter: apiUsage.hunter || 0,
    firecrawl: apiUsage.firecrawl || 0
  },

  // Summary information
  total_api_calls: Object.values(apiUsage).reduce((a, b) => a + b, 0),
  services_used: Object.keys(apiUsage).filter(k => apiUsage[k] > 0).join(','),
  roles_processed: enrichmentData.length,
  created_at: new Date().toISOString(),

  // Enrichment details
  enrichment_details: enrichmentData.map(e => ({
    role: e.role,
    type: e.enrichmentType,
    empresa: e.empresa
  })),

  enrichment_summary: {
    firecrawl_count: enrichmentData.filter(e => e.enrichmentType === 'firecrawl').length,
    hunterIO_count: enrichmentData.filter(e => e.enrichmentType === 'hunterIO').length,
    none_count: enrichmentData.filter(e => e.enrichmentType === 'none').length
  }
};

return [{ json: costRecord }];
